$ErrorActionPreference = 'Stop'
Set-StrictMode -Version 2.0
$Root = Split-Path -Parent $MyInvocation.MyCommand.Path
$InputOos = Join-Path $Root 'INPUT\OOS'
$InputSales = Join-Path $Root 'INPUT\SALES'
$InputMaster = Join-Path $Root 'INPUT\MASTER'
$CacheMaster = Join-Path $Root 'CACHE\MASTER'
$CacheTemp = Join-Path $Root 'CACHE\TEMP'
$Output = Join-Path $Root 'OUTPUT'
$BuildTemp = Join-Path $Root 'BUILD_TEMP'
$TemplatePath = Join-Path $Root 'template\dashboard_template.html'
$LogPath = Join-Path $Output 'UPDATE_LOG.txt'
@($CacheMaster,$CacheTemp,$Output,$BuildTemp)|ForEach-Object{New-Item -ItemType Directory -Force -Path $_|Out-Null}
"START $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')"|Set-Content $LogPath -Encoding UTF8
function Write-Log{param([string]$Message);$Message|Tee-Object -FilePath $LogPath -Append|Out-Host}
function Show-Stage{param([int]$Percent,[string]$Status);Write-Progress -Id 0 -Activity 'OOS Fast Daily Refresh' -Status $Status -PercentComplete $Percent;Write-Log ('[{0,3}%] {1}' -f $Percent,$Status)}
function Stop-Refresh{param([string]$Message);Write-Log "ERROR: $Message";throw $Message}
function Get-Number{param($Value);if($null -eq $Value -or [string]$Value -eq ''){return 0.0};$N=0.0;if([double]::TryParse([string]$Value,[ref]$N)){return $N};return 0.0}
function Get-SafeSum{param($Items,[string]$PropertyName);[double]$Total=0;foreach($Item in @($Items)){if($null -eq $Item){continue};$P=$Item.PSObject.Properties[$PropertyName];if($null -eq $P){continue};$Total+=Get-Number $P.Value};return $Total}
function Get-DateText{param($Value);if($null -eq $Value -or [string]$Value -eq ''){return ''};try{if($Value -is [double] -or $Value -is [int]){return [datetime]::FromOADate([double]$Value).ToString('yyyy-MM-dd')};return ([datetime]$Value).ToString('yyyy-MM-dd')}catch{return [string]$Value}}
function Get-Key{param($Site,$Outlet,$Product);return ("$Site|$Outlet|$Product").Trim().ToUpperInvariant()}
function Get-Fingerprint{param([IO.FileInfo]$File,[switch]$WithHash);$R=[ordered]@{Name=$File.Name;Length=$File.Length;LastWriteTimeUtc=$File.LastWriteTimeUtc.ToString('o')};if($WithHash){$R.Hash=(Get-FileHash -Algorithm SHA256 $File.FullName).Hash};return [pscustomobject]$R}
function Get-HeaderMap{param($Values,[int]$Rows,[int]$Columns,[string[]]$Required,[string]$Label);for($R=1;$R-le [math]::Min(30,$Rows);$R++){$M=@{};for($C=1;$C-le $Columns;$C++){$H=([string]$Values[$R,$C]).Trim();if($H){$M[$H.ToUpperInvariant()]=$C}};$OK=$true;foreach($N in $Required){if(!$M.ContainsKey($N.ToUpperInvariant())){$OK=$false;break}};if($OK){Write-Log "Header detected for $Label at row $R";return [pscustomobject]@{Row=$R;Map=$M}}};throw "Missing headers for $Label`: $($Required -join ', ')"}
function Open-ExcelValues{param([string]$Path);$E=$null;$W=$null;try{$E=New-Object -ComObject Excel.Application;$E.Visible=$false;$E.DisplayAlerts=$false;$W=$E.Workbooks.Open($Path,0,$true);$S=$W.Worksheets.Item(1);$R=$S.UsedRange;return [pscustomobject]@{Values=$R.Value2;Rows=$R.Rows.Count;Columns=$R.Columns.Count}}finally{if($W){$W.Close($false)};if($E){$E.Quit()};[GC]::Collect();[GC]::WaitForPendingFinalizers()}}
function Get-Cell{param($V,[int]$R,$M,[string[]]$Names);foreach($N in $Names){$K=$N.ToUpperInvariant();if($M.ContainsKey($K)){return $V[$R,$M[$K]]}};return ''}
function Save-Index{param([hashtable]$Table,[string]$Path);$O=[ordered]@{};foreach($K in $Table.Keys){$O[$K]=$Table[$K]};[pscustomobject]$O|ConvertTo-Json -Depth 5 -Compress|Set-Content $Path -Encoding UTF8}
try{
 Show-Stage 2 'Checking inputs'
 $Oos=@(Get-ChildItem $InputOos -Filter '*.xlsx' -File);$Sales=@(Get-ChildItem $InputSales -Filter '*.xlsx' -File);$Master=@(Get-ChildItem $InputMaster -Filter '*.xlsx' -File)
 if($Oos.Count-lt 1){Stop-Refresh 'No ASM files'};if($Sales.Count-ne 1){Stop-Refresh 'SALES must contain exactly one xlsx'};if($Master.Count-ne 1){Stop-Refresh 'MASTER must contain exactly one xlsx'};if(!(Test-Path $TemplatePath)){Stop-Refresh 'Missing dashboard template'}
 Write-Log "ASM files: $($Oos.Count)";Write-Log "Sales: $($Sales[0].Name)";Write-Log "Master: $($Master[0].Name)"
 Show-Stage 5 'Loading Product Master'
 $PIPath=Join-Path $CacheMaster 'product_index.json';$PMPath=Join-Path $CacheMaster 'master_manifest.json';$MF=Get-Fingerprint $Master[0] -WithHash;$UseMC=$false;$PI=@{}
 if((Test-Path $PIPath)-and(Test-Path $PMPath)){try{$Old=Get-Content $PMPath -Raw|ConvertFrom-Json;if($Old.Hash-eq$MF.Hash){$UseMC=$true}}catch{}}
 if($UseMC){$C=Get-Content $PIPath -Raw|ConvertFrom-Json;foreach($P in $C.PSObject.Properties){$PI[$P.Name]=$P.Value};Write-Log "Master cache used: $($PI.Count) products"}else{$D=Open-ExcelValues $Master[0].FullName;$H=Get-HeaderMap $D.Values $D.Rows $D.Columns @('BU','Category','Brand','DP Name') 'Product Master';for($R=$H.Row+1;$R-le$D.Rows;$R++){$P=[string](Get-Cell $D.Values $R $H.Map @('DP Name','DP_NAME'));if(!$P){continue};$PI[$P.Trim().ToUpperInvariant()]=[pscustomobject]@{BU=Get-Cell $D.Values $R $H.Map @('BU');Category=Get-Cell $D.Values $R $H.Map @('Category');Segment=Get-Cell $D.Values $R $H.Map @('Segment');Brand=Get-Cell $D.Values $R $H.Map @('Brand');Price=Get-Number (Get-Cell $D.Values $R $H.Map @('Giá GSV','Gia GSV','GSV','Price'))}};Save-Index $PI $PIPath;$MF|ConvertTo-Json|Set-Content $PMPath -Encoding UTF8}
 Show-Stage 12 'Building daily Sales index'
 $SIPath=Join-Path $CacheTemp 'sales_index_today.json';$SMPath=Join-Path $CacheTemp 'daily_manifest.json';$SF=Get-Fingerprint $Sales[0];$UseSC=$false;$SI=@{}
 if((Test-Path $SIPath)-and(Test-Path $SMPath)){try{$Old=Get-Content $SMPath -Raw|ConvertFrom-Json;if($Old.Length-eq$SF.Length-and$Old.LastWriteTimeUtc-eq$SF.LastWriteTimeUtc){$UseSC=$true}}catch{}}
 if($UseSC){$C=Get-Content $SIPath -Raw|ConvertFrom-Json;foreach($P in $C.PSObject.Properties){$SI[$P.Name]=$P.Value};Write-Log "Sales restart cache used: $($SI.Count) keys"}else{$D=Open-ExcelValues $Sales[0].FullName;$H=Get-HeaderMap $D.Values $D.Rows $D.Columns @('Site Name','Outlet','DP Name','Date','KPI') 'Daily Sales';for($R=$H.Row+1;$R-le$D.Rows;$R++){$Site=Get-Cell $D.Values $R $H.Map @('Site Name');$Out=Get-Cell $D.Values $R $H.Map @('Outlet');$Prod=Get-Cell $D.Values $R $H.Map @('DP Name');if(!$Site-or!$Out-or!$Prod){continue};$K=Get-Key $Site $Out $Prod;if(!$SI.ContainsKey($K)){$SI[$K]=[pscustomobject]@{KPI=0.0;Date=''}};$SI[$K].KPI+=Get-Number (Get-Cell $D.Values $R $H.Map @('KPI'));$Date=Get-DateText (Get-Cell $D.Values $R $H.Map @('Date'));if($Date-gt$SI[$K].Date){$SI[$K].Date=$Date}};if(!$SI.Count){Stop-Refresh 'Sales keys = 0'};Save-Index $SI $SIPath;$SF|ConvertTo-Json|Set-Content $SMPath -Encoding UTF8}
 Show-Stage 38 'Reading and mapping ASM files'
 $Mapped=New-Object Collections.Generic.List[object];$US=New-Object Collections.Generic.List[object];$UP=New-Object Collections.Generic.List[object];$Npps=@{};$SM=0;$PM=0;$AR=0
 foreach($F in $Oos){$D=Open-ExcelValues $F.FullName;$H=Get-HeaderMap $D.Values $D.Rows $D.Columns @('Site Name','Outlet','DP Name') $F.Name;for($R=$H.Row+1;$R-le$D.Rows;$R++){$Site=Get-Cell $D.Values $R $H.Map @('Site Name');$Out=Get-Cell $D.Values $R $H.Map @('Outlet','Outlet Code','Store Code');$Prod=Get-Cell $D.Values $R $H.Map @('DP Name','DP_NAME');if(!$Site-or!$Out-or!$Prod){continue};$AR++;$NC=([string]$Site-split'_',2)[0];$Npps[$NC]=[string]$Site;$PR=$PI[[string]$Prod.Trim().ToUpperInvariant()];$SR=$SI[(Get-Key $Site $Out $Prod)];if($SR){$SM++}else{$US.Add([pscustomobject]@{NPP=$Site;Outlet=$Out;DPName=$Prod;Source=$F.Name})};if($PR){$PM++}else{$UP.Add([pscustomobject]@{NPP=$Site;DPName=$Prod;Source=$F.Name})};$T=Get-Number (Get-Cell $D.Values $R $H.Map @('#Stock Target','Stock Target','Stock Target (PCS)'));$A=Get-Number (Get-Cell $D.Values $R $H.Map @('#Stock Actual','Stock Actual','Stock Actual (PCS)'));$G=[math]::Max($T-$A,0);$OP=[string]$Out-split'_',2;$Mapped.Add([pscustomobject][ordered]@{Cycle=Get-Cell $D.Values $R $H.Map @('Cycle');ASM=Get-Cell $D.Values $R $H.Map @('ASM','ASM/SUP');NPPCode=$NC;NPP=[string]$Site;StoreKey="$Site|$Out";StoreCode=$OP[0];StoreName=if($OP.Count-gt1){$OP[1]}else{''};DPName=[string]$Prod;BU=if($PR){$PR.BU}else{''};Category=if($PR){$PR.Category}else{''};Segment=if($PR){$PR.Segment}else{''};Brand=if($PR){$PR.Brand}else{''};SetAudit=Get-Number (Get-Cell $D.Values $R $H.Map @('#Set Audit','Set Audit'));Target=$T;Actual=$A;Gap=$G;KPI=if($SR){$SR.KPI}else{$null};LatestSaleDate=if($SR){$SR.Date}else{''};SalesMatched=[bool]$SR;ProductMatched=[bool]$PR;OOSValue=if($PR){$G*$PR.Price}else{$null}})}}
 if(!$Mapped.Count){Stop-Refresh 'Mapped rows = 0'}
 Show-Stage 75 'Writing validation reports';$VR=[pscustomobject]@{RunDate=Get-Date -Format 'yyyy-MM-dd HH:mm:ss';ASMFiles=$Oos.Count;ASMRows=$AR;NPPDetected=$Npps.Count;SalesKeys=$SI.Count;MappedRows=$Mapped.Count;SalesMatched=$SM;SalesMatchRate=$SM/[math]::Max(1,$Mapped.Count);ProductMatched=$PM;ProductMatchRate=$PM/[math]::Max(1,$Mapped.Count);UnmatchedSales=$US.Count;UnmatchedProduct=$UP.Count;MasterCacheUsed=$UseMC;SalesRestartCacheUsed=$UseSC};$VR|Export-Csv (Join-Path $Output 'VALIDATION_SUMMARY.csv') -NoTypeInformation -Encoding UTF8;$US|Export-Csv (Join-Path $Output 'UNMATCHED_SALES.csv') -NoTypeInformation -Encoding UTF8;$UP|Export-Csv (Join-Path $Output 'UNMATCHED_PRODUCT.csv') -NoTypeInformation -Encoding UTF8
 Show-Stage 82 'Building dashboards';Get-ChildItem $BuildTemp -Force -ErrorAction SilentlyContinue|Remove-Item -Recurse -Force;$BD=Join-Path $BuildTemp 'data';$BN=Join-Path $BuildTemp 'npp';New-Item -ItemType Directory -Force -Path $BD,$BN|Out-Null;$Template=Get-Content $TemplatePath -Raw -Encoding UTF8
 function New-Html{param($Data,[string]$Scope);$J=$Data|ConvertTo-Json -Depth 6 -Compress;$S=ConvertTo-Json $Scope -Compress;return $Template.Replace('</head>',('<script>window.DASH_DATA='+$J+';window.NPP_SCOPE='+$S+';</script></head>'))}
 $MA=$Mapped.ToArray();$SG=$MA|Group-Object NPPCode,NPP,Category,Brand;$SL=New-Object Collections.Generic.List[object];foreach($G in $SG){$F=$G.Group[0];$LD=$G.Group|Where-Object{$_.LatestSaleDate}|Sort-Object LatestSaleDate -Descending|Select-Object -First 1;$SL.Add([pscustomobject][ordered]@{Cycle='';ASM='';NPPCode=$F.NPPCode;NPP=$F.NPP;StoreKey=$F.NPP;StoreCode='';StoreName='All stores';DPName='Category summary';BU=$F.BU;Category=$F.Category;Segment=$F.Segment;Brand=$F.Brand;SetAudit=Get-SafeSum $G.Group 'SetAudit';Target=Get-SafeSum $G.Group 'Target';Actual=Get-SafeSum $G.Group 'Actual';Gap=Get-SafeSum $G.Group 'Gap';KPI=Get-SafeSum $G.Group 'KPI';LatestSaleDate=if($LD){$LD.LatestSaleDate}else{''};SalesMatched=$true;ProductMatched=$true;OOSValue=Get-SafeSum $G.Group 'OOSValue'})};$SA=$SL.ToArray();$SA|ConvertTo-Json -Depth 6 -Compress|Set-Content (Join-Path $BD 'summary.json') -Encoding UTF8;New-Html $SA 'Dashboard tong - tat ca NPP'|Set-Content (Join-Path $BuildTemp 'index.html') -Encoding UTF8
 $Links=@();foreach($G in @($MA|Group-Object NPPCode)){$Dir=Join-Path $BN $G.Name;New-Item -ItemType Directory -Force $Dir|Out-Null;$G.Group|ConvertTo-Json -Depth 6 -Compress|Set-Content (Join-Path $Dir 'data.json') -Encoding UTF8;New-Html $G.Group ([string]$G.Group[0].NPP)|Set-Content (Join-Path $Dir 'index.html') -Encoding UTF8;$Links+=[pscustomobject]@{Code=$G.Name;Name=$G.Group[0].NPP;Path="npp/$($G.Name)/"}}
 $Rows=($Links|Sort-Object Code|ForEach-Object{"<tr><td>$($_.Code)</td><td>$($_.Name)</td><td><a href='$($_.Path)'>OPEN</a></td></tr>"})-join'';"<!doctype html><meta name='viewport' content='width=device-width'><table><tr><th>Code</th><th>NPP</th><th>Link</th></tr>$Rows</table>"|Set-Content (Join-Path $BuildTemp 'links.html') -Encoding UTF8
 $Big=@(Get-ChildItem $BuildTemp -File -Recurse|Where-Object{$_.Length-gt90MB});if($Big.Count){Stop-Refresh "Publish file exceeds 90 MB: $($Big.FullName -join ', ')"}
 Show-Stage 93 'Publishing dashboard files';foreach($N in @('data','npp')){$T=Join-Path $Root $N;if(Test-Path $T){Remove-Item $T -Recurse -Force};Move-Item (Join-Path $BuildTemp $N) $T};Copy-Item (Join-Path $BuildTemp 'index.html') (Join-Path $Root 'index.html') -Force;Copy-Item (Join-Path $BuildTemp 'links.html') (Join-Path $Root 'links.html') -Force
 Show-Stage 97 'Git commit and push';Push-Location $Root;try{git rev-parse --is-inside-work-tree *> $null;if($LASTEXITCODE-ne0){Stop-Refresh 'Not a Git repo'};git add index.html links.html data npp .gitignore UPDATE_FAST_DAILY.ps1 UPDATE_FAST_DAILY.bat;$Status=git status --porcelain;if($Status){git commit -m "Daily OOS refresh $(Get-Date -Format 'yyyy-MM-dd_HH-mm') | NPP $($Npps.Count)";if($LASTEXITCODE-ne0){Stop-Refresh 'git commit failed'};git push;if($LASTEXITCODE-ne0){Stop-Refresh 'git push failed'}}}finally{Pop-Location}
 Write-Progress -Id 0 -Activity 'OOS Fast Daily Refresh' -Completed;Write-Log '[100%] SUCCESS';exit 0
}catch{Write-Progress -Id 0 -Activity 'OOS Fast Daily Refresh' -Completed;Write-Log "FAILED: $($_.Exception.Message)";exit 1}
